.header {
    position:absolute;
    top:5.5mm;
    left:6mm;
    right:6mm;
    height:29mm;
    background:#1e5a32;
    border-radius:9mm 9mm 0 0;
    color:white;
    z-index:1;
}
.header:after {
    content:"";
    position:absolute;
    left:-1mm;
    right:-1mm;
    bottom:-3.5mm;
    height:9mm;
    background:#fffdfa;
    border-top:1.1mm solid #941e31;
    border-radius:0 0 50% 8%;
    transform:skewY(-1.4deg);
}
.header:before {
    content:"";
    position:absolute;
    left:0;
    right:0;
    bottom:-5mm;
    height:5mm;
    border-top:.3mm solid #c99b55;
    z-index:2; transform:skewY(-2deg);
}



.crest { position:absolute; left:8mm; top:2.8mm; width:34mm; height:34mm; border:0.35mm solid #9b1d2d; border-radius:50%; background:#fff; padding:2mm; z-index:3; }
.coffee-logo { position:absolute; right:7mm; top:4mm; width:36mm; height:27mm; object-fit:contain; border:0.35mm solid #9b1d2d; border-radius:6mm; background:#fff; padding:1mm; z-index:3; }
.header-title { position:absolute; left:46mm; top:8mm; font-family:DejaVu Serif,serif; font-size:17pt; font-weight:bold; letter-spacing:.5pt; z-index:3; }
.header-tag { position:absolute; left:46mm; top:18.5mm; color:#e7d9b9; font-family:DejaVu Serif,serif; font-style:italic; font-size:10pt; z-index:3; }
.content { position:relative; z-index:2; }
.law { text-align:center; line-height:1.55; margin-top:0; font-size:7.5pt; }
.law strong { font-size:8pt; }
.law .muted { color:#65776b; }
.main-title { text-align:center; color:#1e5a32; font-family:DejaVu Serif,serif; font-size:19pt; letter-spacing:1.2pt; font-weight:bold; margin:1.1mm 0 1.4mm; }
.serials { width:100%; border-collapse:separate; border-spacing:2mm 0; margin:0 -2mm 1.5mm; }
.serials td { background:#f0f5ef; border:.3mm solid #c9ddc9; border-radius:4mm; padding:1.5mm 3mm; height:10mm; width:33.33%; vertical-align:middle; }
.small-label { display:block; color:#687b70; font-size:7pt; margin-bottom:.5mm; }
.serial-value { display:block; font-weight:bold; font-size:9pt; }
.panel { border:.3mm solid #b8cdb9; border-radius:6mm; padding:4mm 3.5mm 2mm; margin-bottom:2.5mm; position:relative; background:rgba(255,255,255,.56); }
.panel-title { position:absolute; top:-2.5mm; left:4mm; background:#1e5a32; color:white; border-radius:4mm; padding:1.2mm 4mm .9mm; font-weight:bold; font-size:7pt; letter-spacing:.8pt; }
.fields { width:100%; border-collapse:collapse; table-layout:fixed; }
.fields td { height:5.55mm; padding:.45mm 0 .35mm; border-bottom:.25mm dotted #9eb9a0; vertical-align:middle; }
.fields tr:last-child td { border-bottom:none; }
.fields .label { width:17%; color:#718077; font-size:7.3pt; padding-right:1.5mm; }
.fields .value { width:33%; font-size:8.4pt; font-weight:bold; padding-left:2mm; padding-right:2mm; }
.fields .gap { width:1.5%; border:0; }
.authorization { border:.35mm solid #24713c; border-radius:8mm; padding:3.3mm 7mm; margin:0 0 2.5mm; background:#f1f6f0; font-size:9.2pt; line-height:1.55; text-align:justify; }
.authorization b { color:#1e5a32; }
.route-panel { padding-top:4mm; }
.warning { border:.35mm solid #9c1d2c; border-radius:7mm; text-align:center; padding:1.7mm 2mm 1.5mm; margin:0 0 4mm; background:rgba(255,255,255,.8); }
.warning strong { color:#941e2d; font-size:9.4pt; }
.warning div { color:#69796f; font-size:7pt; margin-top:.7mm; }
.lower { width:100%; height:28mm; border-collapse:collapse; margin-bottom:1mm; }
.lower td { vertical-align:middle; }
.printed { width:34%; color:#69796f; font-size:7pt; line-height:1.45; }
.printed b { display:block; color:#29382e; font-size:8.5pt; }
.qr-cell { width:17%; text-align:center; }
.qr { width:18mm; height:18mm; border:.3mm solid #b8cdb9; padding:1mm; background:white; }
.hash { font-size:5.5pt; color:#718077; }

    .signature {
        width:33%;
        text-align:center;
        padding:0 2mm; }
    .signature .line {
        border-bottom:.35mm dashed #444;
         height:12mm; }
    .signature b {
        display:block;
        font-size:8.5pt;
        margin-top:1mm;
    }
    .signature span {
        color:#718077;
        font-size:7pt;
    }
    .stamp-cell {
        width:16%;
        text-align:right;
    }
    .stamp {
        width:27mm;
        height:27mm; o
        bject-fit:contain;
    }

    .endorse {
        margin-top:0;
        padding:4mm 3.5mm 2mm;
    }
    .endorse .panel-title {
        background:#861e2e;
    }
    .endorse-table {
        width:100%;
        border-collapse:separate;
        border-spacing:0;
        border:.3mm solid #b8cdb9;
        border-radius:4mm;
        overflow:hidden;
    }
    .endorse-table td {
        border-right:.25mm solid #b8cdb9;
        height:9mm; padding:1.5mm 1.5mm;
        color:#718077; font-size:6.8pt;
        vertical-align:top;
    }
    .endorse-table td:last-child {
        border-right:0;
    }

    .footer {
        position:absolute;
        bottom:5.5mm; left:6mm;
        right:6mm; height:7mm;
        background:#1e5a32;
        border-radius:0 0 8mm 8mm;
        color:#fff;
        padding:2mm 12mm;
        font-size:6.8pt;
        letter-spacing:.2pt;
        z-index:3;
        border-top:.8mm solid #941e2d;
    }
</style>
</head>
